/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
    var sys_id = event.payload.sys_id;
    var table_name = event.payload.table;
    var url = "/nav_to.do?uri=%2F"+table_name+".do%3Fsys_id%3D"+sys_id+"%26sysparm_view%3Dworkspace";

    return {
        route: null,
        fields: null,
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: "Open Record",
        multiInstField: null,
        targetRoute: null,
        external: {
            url: url
        }
    };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  let user_roles = api.context.session.user.roles;
  //Displaying the Flow Jobs Waiting To Run widget only for admin roles
  let visibility_condition 
      = user_roles.includes("admin");
  return !visibility_condition;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
    var startDateString = event.payload.params.scoreDate;
    var endDateString = startDateString;
    var dateObj = new Date(event.payload.data.timestamp);
    var hours = dateObj.getHours(); 
    var minutes = dateObj.getMinutes();
    var seconds = dateObj.getSeconds();
    var padding = "0";

    if (Number.isNaN(hours) || Number.isNaN(minutes) || Number.isNaN(seconds)) {
        padding = "";
        var time = (event.payload.data.timestamp).split(":", 2);
        hours = parseInt(time[0], 10);
        minutes = parseInt(time[1], 10);
        seconds = parseInt("00", 10);
    }

    if((hours+1)%24 === 0) {
        var endDateObj = new Date(startDateString);
        endDateObj.setDate(endDateObj.getDate()+2);
        var endYear = endDateObj.getFullYear();
        var endMonth = endDateObj.getMonth()+1;
        var endDate = endDateObj.getDate();
        endDateString = endYear + "-" + ("0" + endMonth).slice(-2) + "-" + ("0" + endDate).slice(-2);
    }

    var startTimeString = (padding + hours).slice(-2) + ":" + (padding + minutes).slice(-2) + ":" + (padding + seconds).slice(-2);
    var endTimeString = (padding + ((hours+1)%24)).slice(-2) + ":" + (padding + minutes).slice(-2) + ":" + (padding + seconds).slice(-2);

    var url = "/sysevent_list.do?sysparm_query=name%3Dflow.fire%5Esys_created_onBETWEENjavascript:gs.dateGenerate(%27"+startDateString+"%27%2C%27"+startTimeString+"%27)@javascript:gs.dateGenerate(%27"+endDateString+"%27%2C%27"+endTimeString+"%27)&sysparm_first_row=1&sysparm_view=";

    return {
        route: null,
        fields: null,
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: "Flow Events Produced",
        multiInstField: null,
        targetRoute: null,
        external: {
            url: url
        }
    };
}

